# shellcheck shell=bash
#
# ДОСТАВКА ВЕРДИКТА РЕВЬЮЕРА — ШАГАМИ ДЖОБЫ (тред 088, постановка curator 2026-09-02).
#
# ЧТО ИЗМЕРЕНО И ПОЧЕМУ ЭТО ОДНА БОЛЕЗНЬ, А НЕ ТРИ. Круг по PR #204 (прогон
# 33661622377, голова 181157ad, 2026-09-02T17:33Z): действие упало за 76 с
# (`is_error:true`), `verdict.md` не создан, а шаг-страховка доставил коммент в PR и
# ОТКАЗАЛ на письме в тред — дословно «thread '067-park-lift-narrowing' is PARKED
# behind the round running on PR #204 … and this message says nothing about it».
# Дверь почты сработала верно; отказал звонящий. И тред был запаркован НЕ случайно:
# маршрут карточки curator — «повесил метку → передал ход → запарковался на run:<N>»,
# то есть в правильно исполненном случае ветвь «вердикта нет» доезжает ровно до
# запаркованного треда и не доезжает никогда.
# Ещё два случая того же класса измерены в соседнем контуре за тот же час: (а) агент
# написал вердикт и умер ДО отправки — текст не прочитал никто; (б) вердикт уехал
# письмом и комментом, а формальный статус упал, и страховка напечатала «не сработала
# ни одна из трёх доставок» прямо под самим вердиктом.
# Общий диагноз john (тред 082) в двух словах: ДОСТАВКА ВИСИТ НА АГЕНТЕ, А СУЖДЕНИЕ О
# НЕЙ ВЫНОСИТСЯ ПО НАЛИЧИЮ ФАЙЛА НА ДИСКЕ.
#
# ОТСЮДА ТРИ ВЕЩИ, КОТОРЫЕ ДЕЛАЕТ ЭТОТ ФАЙЛ:
#   1. обязанность агента сокращена до записи `verdict.md`; письмо в тред и коммент в
#      PR делают шаги джобы, и смерть агента ПОСЛЕ записи файла больше не съедает
#      результат круга;
#   2. каждая из трёх доставок (тред, коммент, формальный статус) УЧИТЫВАЕТСЯ ПОИМЕННО
#      (`delivery_mark`/`delivery_summary`), и «не сработала ни одна» печатается,
#      только если это правда;
#   3. любая доставка в тред ПЕРЕЖИВАЕТ ЛЮБОЙ СТОЯЩИЙ ПАРК: стоящий парк ЧИТАЕТСЯ
#      (`park_probe`) и по нему выбирается флаг (`park_flags`) — снять свой, встать
#      рядом с чужим.
#
# ЛОГИКА ЖИВЁТ ЗДЕСЬ, А НЕ В YAML, по той же причине, что и `comms-push.sh`: правило,
# спрятанное в шаге воркфлоу, не гоняется ничем, кроме живого круга ревью ценой ~$2.4.
# Чистые функции ниже покрыты `review-delivery.test.sh`, который поднимает сьюта
# (`src/roles/review-delivery.process.test.ts`).
#
# ИСПОЛЬЗОВАНИЕ:
#   source "${GITHUB_WORKSPACE}/.code/.github/scripts/review-delivery.sh"

# КАТАЛОГ УЧЁТА ДОСТАВОК — общий на все шаги джобы. Шаги делят рабочую директорию, но
# не переменные, поэтому исход каждой доставки кладётся файлом: итоговый шаг читает
# ФАКТ доставки, а не пересказывает догадку о ней.
REVIEW_DELIVERY_DIR="${REVIEW_DELIVERY_DIR:-${GITHUB_WORKSPACE:-.}/.delivery}"

# Записать исход доставки. <имя> — `thread`|`comment`|`status`; <исход> — `ok`|`failed`.
delivery_mark() { # <имя> <исход>
  local name="${1:?delivery_mark: не названа доставка}" state="${2:?delivery_mark: не назван исход}"
  mkdir -p "$REVIEW_DELIVERY_DIR"
  printf '%s\n' "$state" > "${REVIEW_DELIVERY_DIR}/${name}"
}

# Прочитать исход доставки. Файла нет — доставки НЕ БЫЛО (`none`), и это третье
# состояние, а не синоним отказа: шаг мог не дойти до неё вовсе.
delivery_state() { # <имя>
  local name="${1:?delivery_state: не названа доставка}"
  if [ -f "${REVIEW_DELIVERY_DIR}/${name}" ]; then
    tr -d '\r\n' < "${REVIEW_DELIVERY_DIR}/${name}"
  else
    printf 'none'
  fi
}

# ДОСТАВКУ СУДИТ ЦЕЛЬ, А НЕ КОД ВЫХОДА КЛИЕНТА (тред 122, решение john 2026-09-05:
# «РАЗРЕШАЮ — отказная ветвь ПЕРЕЧИТЫВАЕТ цель, прежде чем объявить письмо непришедшим»).
#
# ЧТО ИЗМЕРЕНО. Круг по PR #260 (прогон 33817342342, голова 81e8218c) умер не на суждении,
# а на КВИТАНЦИИ: коммент вердикта был ЗАПИСАН (`id 5533463712`, `created_at = updated_at =
# 2026-09-03T23:29:40Z`, первая строка `verdict: approve`), а через одиннадцать секунд
# клиент получил `23:29:51Z non-200 OK status code: 502 Bad Gateway` и напечатал «коммент в
# PR #260 НЕ доставлен». Повтора POST не было — на тот круг приходится ровно один коммент
# вердикта, то есть сервер записал, а потерялся ИМЕННО ОТВЕТ. Джоба покраснела, гард 1
# честно сказал STOP на доставленном вердикте, и был оплачен полный второй круг
# (33819571043), вынесший ТОТ ЖЕ `approve`.
#
# КЛАСС: судьёй доставки служит код выхода клиента, и потерянная квитанция неотличима от
# непришедшего письма. Чинятся ВСЕ пять мест приёма (два в доставке вердикта, одно в
# формальном статусе, два в итоге доставок), а не одно сработавшее: чинить один названный
# случай при четырёх таких же — это чинить образец.
#
# ГРАНИЦЫ ПРАВКИ ПРИНЯТЫ john КАК ЧАСТЬ РЕШЕНИЯ, а не как детали реализации:
#   1. успешная ветвь не трогается вовсе — на нулевом коде клиента проба НЕ ЗОВЁТСЯ ни
#      разу (машинно проверено счётчиком вызовов в `review-delivery.test.sh`);
#   2. перечитывание НЕ создаёт вторую запись — не нашли своей, значит доставка
#      несостоявшаяся; повторного POST/push нет ни на одной ветви, в том числе при отказе
#      самой пробы: два вердикта на одной странице хуже одного потерянного круга;
#   3. новой нормы не вводится — шаг возвращается к тому, что он и так объявляет
#      («доставлено / не доставлено»).
#
# ИЗВЕСТНОЕ ВЫРОЖДЕНИЕ, И ОНО НАЗВАНО ВСЛУХ: если запись ещё не видна из-за задержки
# репликации GitHub, проба вернёт «не нашла», и доставка объявится несостоявшейся — то есть
# поведение станет СЕГОДНЯШНИМ. Худший случай равен нынешнему, нового не заводится.
#
# ПРОБА РАЗЛИЧАЕТ ТРИ ИСХОДА КОДОМ ВЫХОДА, А НЕ ТЕКСТОМ: `0` — своя запись найдена; `1` —
# записи нет; `≥2` — перечитывание САМО отказало (сеть, `gh`, разбор). Третий исход
# обязателен: без него «не смог посмотреть» неотличимо от «не доехало», и это тот же дефект
# классом ниже.
#
# Возвращает `0`, если доставка СОСТОЯЛАСЬ (клиент вышел нулём либо запись найдена), иначе
# `1`. Учёта не ведёт — его делает `delivery_attempt` ниже; итоговым шагам учитывать нечего,
# и они зовут этот предикат напрямую.
delivery_confirmed() { # <имя доставки для лога> <код выхода клиента> <команда-проба> [аргументы пробы...]
  local name="${1:?delivery_confirmed: не названа доставка}" code="${2:?delivery_confirmed: не назван код выхода клиента}"
  shift 2
  # ГРАНИЦА 1 МАШИННО: клиент ответил нулём — выходим ДО пробы, и ни одного лишнего вызова
  # на нормальном такте не делается (счётчик вызовов стаба в тесте держит это правило).
  if [ "$code" = "0" ]; then
    return 0
  fi
  if [ "$#" -eq 0 ]; then
    echo "::error::доставка '${name}': клиент вышел кодом ${code}, а пробы перечитывания не названо — судить о цели нечем."
    return 1
  fi
  local probe_code=0
  "$@" || probe_code=$?
  case "$probe_code" in
    0)
      # НАЗВАННАЯ СТРОКА, А НЕ МОЛЧАНИЕ: человек, читающий прогон, обязан видеть, что
      # квитанция потеряна, а запись на месте, — иначе зелёный шаг после `502` в логе
      # читается как чужая ошибка.
      echo "::warning::доставка '${name}': клиент вышел кодом ${code}, но СВОЯ ЗАПИСЬ В ЦЕЛИ НАЙДЕНА — потеряна квитанция, а не письмо (тред 122). Повторной записи не делаем, доставка засчитана."
      return 0
      ;;
    1)
      echo "::error::доставка '${name}' НЕ состоялась: клиент вышел кодом ${code}, и перечитывание цели своей записи не нашло."
      return 1
      ;;
    *)
      echo "::error::доставка '${name}': клиент вышел кодом ${code}, и ПЕРЕЧИТЫВАНИЕ ЦЕЛИ САМО ОТКАЗАЛО (код ${probe_code}) — доставка объявлена несостоявшейся, потому что «не смог посмотреть» не есть «доехало»."
      return 1
      ;;
  esac
}

# ТО ЖЕ САМОЕ С ПОИМЁННЫМ УЧЁТОМ — для трёх доставок вердикта (`thread`|`comment`|`status`).
# `delivery_mark` сохраняет сегодняшний смысл: правится ТО, ЧТО в него кладётся, а не то,
# как читается итог.
delivery_attempt() { # <имя доставки> <код выхода клиента> <команда-проба> [аргументы пробы...]
  local name="${1:?delivery_attempt: не названа доставка}"
  if delivery_confirmed "$@"; then
    delivery_mark "$name" ok
    return 0
  fi
  delivery_mark "$name" failed
  return 1
}

# СКОЛЬКО СВОИХ ЗАПИСЕЙ НАШЛА ПРОБА — В ЕЁ ЖЕ ТРЁХ ИСХОДАХ. Не число в ответе — это не «ноль
# записей», а НЕПОНЯТЫЙ ОТВЕТ, и он идёт третьим исходом (`2`), а не вторым: молчаливое
# приведение «пусто → ноль» превратило бы отказ разбора в «не доехало».
delivery_probe_count() { # <ответ разбора> <что перечитывали>
  local count="${1:-}" what="${2:-цель}"
  case "$count" in
    '' | *[!0-9]*)
      echo "::error::перечитывание ${what} дало не число, а '${count}' — считать этот ответ нулём записей нельзя." >&2
      return 2
      ;;
  esac
  [ "$count" -gt 0 ]
}

# ПРОБА КОММЕНТА В PR. Опознаётся ТОЛЬКО литералами, которые в теле УЖЕ ЕСТЬ: добавить в
# тело маркер ради опознания нельзя — это смена формы сообщения, то есть норма (граница 3).
#
# ЛИТЕРАЛА ДВА, И ОБА ОБЯЗАНЫ БЫТЬ В ОДНОМ И ТОМ ЖЕ КОММЕНТЕ. Одного `RUN_ID` мало: за один
# прогон в PR уходят ДВА коммента (вердикт и итог доставок), и оба несут номер прогона —
# проба итога приняла бы коммент вердикта за свой и объявила доставку состоявшейся. Второй
# литерал — постоянная фраза своего текста; она же одна не годится, потому что повторяется
# из круга в круг. Пара «номер прогона + фраза этого сообщения» уникальна и не требует ни
# часов, ни окна.
#
# Коды выхода — по общему договору: `0` нашла, `1` нет, `2` отказала сама.
delivery_probe_pr_comment() { # <номер PR> <литерал 1 (номер прогона)> <литерал 2 (фраза своего текста)>
  local pr="${1:?delivery_probe_pr_comment: не назван PR}" one="${2:?}" two="${3:?}" raw found
  # ЗАПРОС И РАЗБОР — ДВУМЯ КОМАНДАМИ: `--jq` внутри `gh` считает gojq, и отказ ФИЛЬТРА
  # отдаёт тот же ненулевой код, что отказ API, — «не разобрал» тогда рядится в «GitHub
  # отказал». Здесь это разные ветви с разными строками.
  if ! raw="$(gh api --paginate "repos/${GITHUB_REPOSITORY:?delivery_probe_pr_comment: не назван GITHUB_REPOSITORY}/issues/${pr}/comments" 2>&1)"; then
    echo "::error::перечитывание комментов PR #${pr} отказало (запрос): ${raw}" >&2
    return 2
  fi
  if ! found="$(printf '%s' "$raw" | jq -s -r --arg one "$one" --arg two "$two" \
      '[ .[][] | select((.body // "") | (contains($one) and contains($two))) ] | length' 2>&1)"; then
    echo "::error::ответ GitHub со списком комментов PR #${pr} не разобран: ${found}" >&2
    return 2
  fi
  delivery_probe_count "$found" "комментов PR #${pr}"
}

# ПРОБА ФОРМАЛЬНОГО REVIEW-СТАТУСА — ЕДИНСТВЕННАЯ, ОПОЗНАЮЩАЯ ПО ОКНУ, И ЭТО НАЗВАНО ЧЕСТНО.
# Тело статуса КОНСТАНТНО от круга к кругу («… доставка 3 из 3 …»), номера прогона в нём НЕТ,
# а добавить его туда нельзя по границе 3 (форма сообщения не меняется). Значит опознание
# идёт по тройке: автор `github-actions`, состояние = выставляемому, `submitted_at` внутри
# окна.
#
# СЛАБОЕ МЕСТО: от вердикта ПРЕДЫДУЩЕГО круга с тем же состоянием эту запись отделяет ОКНО,
# а не текст. Начало окна снимается непосредственно ПЕРЕД записью, поэтому промахнуться оно
# может только на расхождении часов раннера и GitHub — и промахивается в БЕЗОПАСНУЮ сторону:
# часы раннера впереди → запись не найдена → доставка объявлена несостоявшейся, то есть
# поведение сегодняшнее.
delivery_probe_pr_review() { # <номер PR> <состояние (APPROVED|CHANGES_REQUESTED)> <начало окна, ISO-8601 UTC>
  local pr="${1:?delivery_probe_pr_review: не назван PR}" state="${2:?}" since="${3:?}" raw found
  if ! raw="$(gh api --paginate "repos/${GITHUB_REPOSITORY:?delivery_probe_pr_review: не назван GITHUB_REPOSITORY}/pulls/${pr}/reviews" 2>&1)"; then
    echo "::error::перечитывание review-статусов PR #${pr} отказало (запрос): ${raw}" >&2
    return 2
  fi
  if ! found="$(printf '%s' "$raw" | jq -s -r --arg state "$state" --arg since "$since" \
      '[ .[][]
         | select(((.user.login // "") | startswith("github-actions")))
         | select(.state == $state)
         | select((.submitted_at // "") >= $since) ] | length' 2>&1)"; then
    echo "::error::ответ GitHub со списком review-статусов PR #${pr} не разобран: ${found}" >&2
    return 2
  fi
  delivery_probe_count "$found" "review-статусов PR #${pr}"
}

# ПРОБА ПИСЬМА В ТРЕД — ПО СВОЕМУ ФАЙЛУ В УДАЛЁННОЙ ЛЕНТЕ, а не по литералу в теле, и это
# ОТСТУПЛЕНИЕ ОТ ФОРМЫ ПОСТАНОВКИ (§3.2 называла номер прогона), сделанное по её же доводу.
# Довод: за один прогон в ОДИН И ТОТ ЖЕ тред уходят два письма (вердикт и итог доставок), и
# оба несут номер прогона — литерал принял бы чужое письмо за своё. Путь файла, который
# только что создала наша же запись, не спутывается ни с чем и в тело ничего не добавляет
# (граница 3 цела).
#
# ЧИТАЕТСЯ `FETCH_HEAD`, А НЕ ДИСК, И ЭТО НЕ СТИЛЬ. К моменту пробы письмо УЖЕ ЛЕЖИТ в
# рабочем дереве `.comms-fallback` и уже закоммичено локально — вопрос ровно в том, уехало
# ли оно. Проба по диску отвечала бы «доставлено» всякий раз, когда не уехало НИЧЕГО, то
# есть врала бы именно в том случае, ради которого писана.
delivery_probe_thread_file() { # <путь файла письма от корня чекаута почты>
  local path="${1:-}" out found
  # ПУСТОЙ ПУТЬ — ТРЕТИЙ ИСХОД, А НЕ ВТОРОЙ, и `${1:?}` здесь стоять не может: в
  # неинтерактивном bash он убивает ШАГ целиком, то есть отказ пробы съедал бы и отказную
  # ветвь, ради которой она писана.
  if [ -z "$path" ]; then
    echo "::error::перечитывание ленты почты невозможно: имя своего файла письма не определено." >&2
    return 2
  fi
  if [ -z "${MAIL_REMOTE:-}" ]; then
    echo "::error::перечитывание ленты почты невозможно: MAIL_REMOTE не задан." >&2
    return 2
  fi
  if ! out="$(git -C .comms-fallback fetch --no-tags "$MAIL_REMOTE" comms 2>&1)"; then
    echo "::error::перечитывание ленты почты отказало (git fetch): ${out}" >&2
    return 2
  fi
  if ! found="$(git -C .comms-fallback ls-tree -r --name-only FETCH_HEAD -- "$path" 2>&1)"; then
    echo "::error::перечитывание ленты почты отказало (git ls-tree): ${found}" >&2
    return 2
  fi
  [ -n "$found" ]
}

# ПОЛЕ ИЗ ШАПКИ `verdict.md` — `verdict`, `pr`, `waiting-on`. Читается только шапка
# (первые пять строк): дальше идёт текст вердикта, и слово `pr:` в теле не должно
# подменять якорь. Пустая строка в ответе значит «поля нет», а не «поле пустое».
verdict_field() { # <файл> <поле>
  local file="${1:?verdict_field: не назван файл}" field="${2:?verdict_field: не названо поле}"
  [ -f "$file" ] || return 0
  head -n 5 "$file" | tr -d '\r' \
    | grep -iE "^${field}:[[:space:]]*" | head -1 \
    | sed -E "s/^[^:]*:[[:space:]]*//; s/[[:space:]]+$//"
}

# СТОЯЩИЙ ПАРК ИЗ ОТКАЗА ДВЕРИ. Значение парка берётся из ТЕКСТА двери, а не вычисляется
# вторым разбором ленты: второй разбор был бы вторым мнением о парке, и разошёлся бы он
# ровно в тот день, когда это дороже всего.
#
# ОТКАЗОВ, НАЗЫВАЮЩИХ ПАРК, ДВА, И ЧИТАЮТСЯ ОБА (тред 127).
#   · ОТКАЗ ПРО СЕНТИНЕЛ (`park-seen.ts:156`, сегодняшняя дорога `park_probe`) — «the park
#     standing on '<тред>' is '<значение>' (…)». Дверь отдаёт его ВСЕМУ, что пишет, включая
#     машинного писателя, потому что сверка `--park-lifted` стои́т ПЕРВОЙ из всех парковых
#     развилок;
#   · ОТКАЗ ПРО МОЛЧАНИЕ (`park-seen.ts:195`) — «'--parked-on run:204' if the question still
#     stands». Его получает поднятая сессия, написавшая в парк без флага; `park_probe` его
#     больше не видит (см. её шапку), но функция это по-прежнему УМЕЕТ: тот же текст приходит
#     в лог шага при настоящей записи, и разбирать его — та же одна дверь, а не второе мнение.
# Тексты непересекающиеся, поэтому порядок проб — не выбор из двух правд, а один разбор двух
# форм одного и того же предложения.
park_value_of() { # <текст отказа двери>
  local text="${1:-}" value
  value="$(printf '%s' "$text" | grep -oE "the park standing on '[^']+' is '[^']+'" | head -1 \
    | sed -E "s/.* is '//; s/'$//")"
  if [ -z "$value" ]; then
    value="$(printf '%s' "$text" | grep -oE "'--parked-on [^']+'" | head -1 \
      | sed -E "s/^'--parked-on //; s/'$//")"
  fi
  printf '%s' "$value"
}

# ЧТО ЭТО ПИСЬМО ГОВОРИТ О СТОЯЩЕМ ПАРКЕ (требование C постановки 088). Правило одно
# и общее для обеих ветвей — и «вердикт есть», и «вердикта нет»:
#   · парк стои́т за ЭТИМ САМЫМ кругом (`run:<этот PR>` либо `pr:<этот PR>`) — письмо
#     его СНИМАЕТ и называет: круг завершён, пусть и без продукта, и это правда;
#   · парк стои́т за чем-то другим (человек, другой прогон, другой PR) — письмо встаёт
#     РЯДОМ (`--parked-on <ровно то значение, что стои́т>`): чужой парк снимать нечем,
#     и врать о нём нельзя;
#   · парка нет — без флагов.
# Слепое `--park-lifted run:<PR>` чинило бы ровно один случай из четырёх: названный не
# про тот парк, что стои́т, — ОТКАЗ записи (park-seen.ts:149), то есть письмо теряется
# так же, как теряется сегодня.
park_flags() { # <значение стоящего парка (пусто — парка нет)> <номер PR>
  local value="${1:-}" pr="${2:?park_flags: не назван номер PR}"
  [ -n "$value" ] || return 0
  if [ "$value" = "run:${pr}" ] || [ "$value" = "pr:${pr}" ]; then
    printf -- '--park-lifted %s' "$value"
  else
    printf -- '--parked-on %s' "$value"
  fi
}

# АДРЕСАТ ХОДА: объявлен агентом или выведен правилом (требование A постановки 088).
# Суждение агента не выбрасывается — оно объявляется строкой `waiting-on:` в шапке
# `verdict.md`; но доставка на нём не висит. Строки нет либо роли нет в конфиге —
# берётся детерминированное правило (approve → curator, needs-fixes → автор PR), и
# письмо ГОВОРИТ, что адресат выведен, а не объявлен.
# Печатает две колонки: `<роль|-> <declared|derived|none>`.
review_waiting_on() { # <объявленная роль|пусто> <объявленная существует: 1|0> <вердикт> <роль автора PR|пусто> <роль автора существует: 1|0>
  local declared="${1:-}" declared_ok="${2:-0}" verdict="${3:-}" author="${4:-}" author_ok="${5:-0}"
  if [ -n "$declared" ] && [ "$declared_ok" = "1" ]; then
    printf '%s declared' "$declared"
    return 0
  fi
  case "$verdict" in
    approve) printf 'curator derived' ;;
    needs-fixes)
      if [ -n "$author" ] && [ "$author_ok" = "1" ]; then
        printf '%s derived' "$author"
      else
        printf -- '- none'
      fi
      ;;
    *) printf -- '- none' ;;
  esac
}

# ЧТО ИМЕННО НЕ ДОЕХАЛО — одной строкой, по ФАКТУ доставки. Формулировка «не сработала
# ни одна из трёх доставок» печатается, только если это правда: под живым вердиктом,
# уехавшим письмом и комментом, она была ложью (случай (б), тред 082).
delivery_summary() { # <исход треда> <исход коммента> <исход статуса>
  local thread="${1:-none}" comment="${2:-none}" status="${3:-none}"
  local delivered="" missing="" name state
  for pair in "письмо в тред:${thread}" "коммент в PR:${comment}" "формальный review-статус:${status}"; do
    name="${pair%:*}"
    state="${pair##*:}"
    if [ "$state" = "ok" ]; then
      delivered="${delivered:+${delivered}, }${name}"
    else
      missing="${missing:+${missing}, }${name}"
    fi
  done
  if [ -z "$missing" ]; then
    printf 'все три доставки прошли: %s.' "$delivered"
  elif [ -z "$delivered" ]; then
    printf 'не сработала ни одна из трёх доставок: %s.' "$missing"
  else
    printf 'доставлено: %s. НЕ доставлено: %s.' "$delivered" "$missing"
  fi
}

# ПОЧЕМУ КРУГ КОНЧИЛСЯ БЕЗ ВЕРДИКТА — ПО МАШИННЫМ ПОЛЯМ ТРАНСКРИПТА, А НЕ ПО РАЗБОРУ
# ПРОЗЫ (постановка curator, тред 118).
#
# ЧТО ИЗМЕРЕНО. Прогон 33762234440 (`Claude PR Review`, PR #239, голова 97e22acb): джоба
# `review` отработала 77 секунд, `verdict.md` не создан, а последняя запись
# `claude-execution-output.json` несёт `api_error_status: 429`, `terminal_reason:
# "api_error"`, `is_error: true`, `result: "You've hit your session limit · resets 1:40pm
# (UTC)"` — сессия ревьюера упёрлась в лимит АККАУНТА посреди круга. Класс не единичный:
# тот же 429 измерен в прогоне 33787502420 (2026-09-03T17:56Z, ресет `6:40pm`) и в круге
# по PR #204 (ресет `18:00Z`, тред 077). Здоровый круг для сравнения — прогон
# 33797264710: `is_error: false`, `api_error_status: null`, `terminal_reason:
# "completed"`.
#
# ПОЧЕМУ ЭТО НЕ КОСМЕТИКА. Общий совет ветви «вердикта нет» — «перезапусти круг руками» —
# при 429 АКТИВНО ВРЕДЕН ровно так же, как он был вреден на самопропуске: пока лимит
# стои́т, второй круг упрётся в него и сгорит впустую. По #239 автора спас случай (он
# перезапустил в 13:46Z, после ресета 13:40Z); по #204 ресет стоял на 18:00Z, и ранний
# перезапуск по совету письма заплатил бы за ничто.
#
# ПОЛЯ — МАШИННЫЕ, СТРОКА `result` — ДОСЛОВНАЯ. Время ресета лежит в `result` открытым
# текстом, но парсер его в дату здесь не строится намеренно: формат этой строки — текст
# модели, его никто не обещал, и разбор стал бы новым источником вранья в письме, которое
# существует ради правды о причине. Письмо цитирует строку как есть.
#
# Печатает ОДНО слово — класс причины, а нет причины (или нечего читать) — НИЧЕГО:
#   · `limit`            — `api_error_status` == 429, лимит аккаунта;
#   · `api_error:<код>`  — иная ошибка API, код назван полем;
#   · `<terminal_reason>` — прочее терминальное как есть (обрыв по ходам, отказ модели);
#   · `error`            — `is_error: true` и больше ничего различимого;
#   · пусто              — файла нет, он пуст, не разбирается ИЛИ отказа в нём нет.
# Пустой ответ значит «причина неизвестна», и письмо тогда печатает СЕГОДНЯШНИЙ общий
# текст без изменений: неизвестная причина не должна становиться выдуманной.
review_failure_cause() { # <файл транскрипта (execution_file); пусто — причины нет>
  local file="${1:-}" cause
  [ -n "$file" ] && [ -s "$file" ] || return 0
  cause="$(jq -r '
    ((if type == "array" then .[-1] else . end) // {}) as $r
    | ($r.api_error_status // null) as $st
    | (($r.terminal_reason // "") | tostring) as $tr
    | if $st != null and ($st | tostring) == "429" then "limit"
      elif $st != null then "api_error:\($st)"
      elif $tr != "" and $tr != "completed" then $tr
      elif $r.is_error == true then "error"
      else "" end' "$file" 2>/dev/null)" || return 0
  [ "$cause" = "null" ] && cause=""
  printf '%s' "$cause"
}

# СТРОКА `result` ПОСЛЕДНЕЙ ЗАПИСИ — ДОСЛОВНО, без разбора (см. шапку выше). Пусто, если
# файла нет, он не разбирается или поля в нём нет.
review_failure_result() { # <файл транскрипта>
  local file="${1:-}" text
  [ -n "$file" ] && [ -s "$file" ] || return 0
  text="$(jq -r '
    ((if type == "array" then .[-1] else . end) // {}) as $r
    | ($r.result // "") | tostring' "$file" 2>/dev/null)" || return 0
  [ "$text" = "null" ] && text=""
  printf '%s' "$text"
}

# КРАСНЕТЬ ИЛИ НЕТ — ОДНИМ ПРЕДИКАТОМ, А НЕ БЕЗУСЛОВНОЙ ЕДИНИЦЕЙ В ХВОСТЕ ШАГА
# (замер curator, тред 088, чтение головы eef94e71).
#
# ЧТО ИЗМЕРЕНО. Переезд доставки в шаги сделал итоговый шаг красным НА САМОПРОПУСКЕ:
# `claude-code-action` пропускает сам себя, когда `claude-review.yml` ветки разошёлся с
# дефолтной, `verdict.md` не создан, ни одна `delivery_mark` не поставлена — и хвост
# шага выходил `1` безусловно. До переезда этот путь был ЗЕЛЁНЫМ: базовый шаг-страховка
# на успешной доставке выходил `0`.
#
# ПОЧЕМУ ЗЕЛЁНЫЙ ЗДЕСЬ — РЕШЕНИЕ, А НЕ ВКУС (тред 046, прогон 30643932101 по #106).
# Самопропуск — не поломка, а сработавший гард против промпт-инъекции правкой воркфлоу,
# и адресат о нём уже извещён обоими каналами. Красный прогон `Claude PR Review` читает
# смотритель (`notifier-watch.yml`, джоба `alarm`, разморожен 2026-09-02, тред 073) —
# читает как «доставка потеряна» и поднимает пару `dev-core`, которой чинить нечего.
# Класс НЕ редкий: самопропуск ловит любую ветку, чей `claude-review.yml` разошёлся с
# дефолтной, — после merge этого PR разойдётся каждая открытая ветка старше него.
# Отсечка стои́т ТАМ ЖЕ, ГДЕ КЛАСС РОЖДАЕТСЯ (шаг статуса), и последний шаг обязан её
# повторить — иначе она переехала и перестала работать.
#
# И ТОЛЬКО ЕЁ. Все прочие пути «вердикта нет» (дефект H2, обрыв по ходам, отказ модели)
# и все пути «вердикт есть, доставка неполна» остаются КРАСНЫМИ — это требование B
# постановки, и оно не ослабляется. Отказ самой доставки в ветви самопропуска красным
# тоже остаётся, но судит его не этот предикат: он о том, что доставлять, а молчание о
# несостоявшемся ревью — потеря, и звонок смотрителя по ней по адресу.
#
# Печатает код выхода итогового шага: `0` либо `1`.
delivery_exit_code() { # <самопропуск: 1|0> <вердикт есть: 1|0> <исход треда> <исход коммента> <исход статуса>
  local self_skip="${1:-0}" verdict="${2:-0}" thread="${3:-none}" comment="${4:-none}" status="${5:-none}"
  if [ "$thread" = "ok" ] && [ "$comment" = "ok" ] && [ "$status" = "ok" ]; then
    printf '0'
    return 0
  fi
  if [ "$self_skip" = "1" ] && [ "$verdict" != "1" ]; then
    printf '0'
    return 0
  fi
  printf '1'
}

# ОТКАЗ ДОСТАВКИ АДРЕСУЕТСЯ АВТОРУ PR (решение john 2026-09-03, тред 094, чат ~16:22Z:
# «ДВЕРЬ НЕ ТРОГАЕМ, ОТКАЗ АДРЕСУЕМ АВТОРУ»).
#
# ЧТО ИЗМЕРЕНО. Встать РЯДОМ с ЧУЖИМ `run:`/`pr:`-парком дверь не даёт: `run:<чужой PR>`
# с завершившимся кругом — «the outcome … has ALREADY FINISHED» (тред 032), `pr:<чужой
# PR>` — «Add '--park-mover <participant>'», а имени двигателя в отказе про СТОЯЩИЙ парк
# нет (тред 061). Оба отказа правильные, и предел объявлен в `docs/protocol-reference.md`.
#
# ЧТО БЫЛО ТИХОГО В ГРОМКОМ ПРОВАЛЕ. Сам провал громкий (`::error::`, `thread failed`,
# красная джоба), но у громкости был второй, тихий ход: красный `Claude PR Review` читает
# смотритель (`notifier-watch.yml`) и звонит в стоячий адрес отказа уведомителя с ходом на
# `dev-core` — роль, у которой в предмете дела нет. АВТОР PR, чей вердикт не доехал, не
# позван вовсе, а тред стои́т за чужим парком, и ход по вердикту не передан никому: молчание
# держится, пока человек не прочтёт красный прогон руками.
#
# ЛЕЧИТСЯ АДРЕСАЦИЯ, И ТОЛЬКО ОНА. Дверь и её отказы не смягчаются ни на букву; не легло
# письмо в тред PR — то же самое сообщение едет в ПРИЁМНИК стоячего адреса с ходом на
# АВТОРА PR (`role:` из описания — тот же источник, которым передают ход уведомители).
# Приёмник остаётся местом ЗАПИСИ события, а ход по вердикту уходит тому, кто может
# действовать: перевесить метку, перепарковаться, донести вердикт руками.
#
# АДРЕС — СЛАГ, А НЕ ИМЯ КАТАЛОГА (постановка curator, тред 125, 2026-09-04).
#
# ЧТО БЫЛО НЕ ТАК. Приёмник стоял здесь ЛИТЕРАЛОМ (`--thread <NNN-слаг>`), а второй писатель
# того же класса звонков — `notifier-watch.yml` — адресует слагом (`--ensure-thread`). Пока
# первый приёмник открыт, разницы не видно; но закрытие приёмника — НОРМАЛЬНОЕ событие
# устава стоячего адреса (решение john 2026-09-03, тред 080), и в тот день письмо по
# литералу продолжило бы ДОСТАВЛЯТЬСЯ (дверь письмо в закрытый тред принимает — от
# машинного писателя всегда), кандидатом тред бы не стал и роль бы не поднялась. Красноты
# не будет нигде: тихая потеря звонка об отказе доставки вердикта — ровно тот класс, ради
# которого стоячий адрес и заведён.
#
# ОТСЮДА: здесь живёт СЛАГ, а какой тред его сейчас исполняет — решает дверь
# (`--ensure-thread`: старший открытый и непаркованный приёмник этого слага, а нет такого —
# открывает следующий). Номер в переопределении дверь отказывает по имени
# (`unreadableReceiverSlug`), поэтому и переменная называется адресом, а не тредом: имя, за
# которым читатель ищет номер, — половина того же дефекта.
REVIEW_ESCALATION_ADDRESS="${REVIEW_ESCALATION_ADDRESS:-notifier-down}"
# ЗАГОЛОВОК И СОСТАВ НОВОГО ПРИЁМНИКА — ДОСЛОВНО ТЕ ЖЕ, ЧТО ОБЪЯВЛЯЕТ `notifier-watch.yml`,
# и это не копипаста, а требование: приёмник открывает ТОТ, кто позвонил первым после
# закрытия прошлого, и роспись адреса не должна зависеть от того, кто это оказался.
# Переопределения им не дано намеренно — адрес один, и второй его состав был бы вторым
# мнением о том, кого этот звонок касается. Каждый участник сверяется дверью с конфигом:
# неизвестный завалил бы доставку внутри аварии.
REVIEW_ESCALATION_TITLE="Стоячий адрес: отказ уведомителя"
REVIEW_ESCALATION_PARTICIPANTS="github,dev-core,curator"

# ФЛАГИ АДРЕСАЦИИ ОДНОГО ПИСЬМА — ПО ОДНОМУ АРГУМЕНТУ НА СТРОКУ (читается `mapfile`,
# потому что заголовок адреса несёт пробелы и словоделением его не передать).
# Форм адреса две, и они не смешиваются:
#   · `<NNN-слаг>`      — ИМЕНОВАННЫЙ тред: у ветви вердикта адресат один и известен
#                         (тред PR из описания), выбирать там нечего;
#   · `address:<слаг>`  — СТОЯЧИЙ адрес: приёмник выбирает дверь, а не этот файл.
# Правило выбора приёмника здесь НЕ повторяется даже частично: второй разбор ленты был бы
# вторым мнением о том, кто сейчас исполняет адрес, и разошёлся бы он ровно в тот день,
# когда приёмник сменился (это и есть цена, названная в `notifier-mute.sh`, — там второй
# разбор неизбежен, потому что ленту надо ЧИТАТЬ; здесь письмо только пишется).
address_flags() { # <адрес: <NNN-слаг> либо address:<слаг>>
  local address="${1:?address_flags: не назван адрес}"
  case "$address" in
    address:?*)
      printf -- '--ensure-thread\n%s\n--title\n%s\n--participants\n%s\n' \
        "${address#address:}" "$REVIEW_ESCALATION_TITLE" "$REVIEW_ESCALATION_PARTICIPANTS"
      ;;
    address:)
      echo "address_flags: 'address:' без слага — стоячий адрес не назван." >&2
      return 1
      ;;
    # Пустой адрес сюда не доходит: его назвал по имени `${1:?}` выше — то есть отказ
    # один, а не два в разных формах.
    *) printf -- '--thread\n%s\n' "$address" ;;
  esac
}

# КУДА ЛЕГЛО — СПРАШИВАЕТСЯ У ДЕРЕВА, А НЕ У ВЫВОДА КОМАНДЫ (тот же приём, что в
# `notifier-watch.yml`): у стоячего адреса приёмник мог быть ОТКРЫТ этой же записью, и его
# номер отсюда иначе не узнать. Дерево перед записью чистое (`reset --hard FETCH_HEAD`),
# поэтому всё новое под `agent-comms/` — ровно то, что записала доставка.
# Хвост имени не пересуживается (`[^/"]`, а не форма слага): что там законно, уже сказала
# дверь, а этой функции надо назвать каталог, в который дверь написала.
landed_thread() { # <вывод git status --porcelain --untracked-files=all -- agent-comms>
  printf '%s\n' "${1:-}" \
    | sed -nE 's#^.. "?agent-comms/([0-9]{3}-[^/"]+)/.*#\1#p' | sort -u | head -1
}

# ФАКТИЧЕСКИЙ ПРИЁМНИК ПОСЛЕДНЕЙ УДАВШЕЙСЯ ДОСТАВКИ — переменная, а не вывод: её читает
# `escalate_undelivered`, чтобы назвать в логе тред, в который письмо ЛЕГЛО. Пусто — не
# легло никуда, и это третье состояние, а не синоним слага.
REVIEW_LANDED_THREAD=""

# РОЛЬ АВТОРА PR ИЗ ОПИСАНИЯ. Regex тот же, терпимый к оформлению, что в `merge-notify.yml`
# и в шагах `claude-review.yml`: строки в бэктиках уже один раз ослепили парсер (PR #16), и
# второго ФОРМАТА одного поля здесь не заводится. Копии в шагах воркфлоу остаются жить своей
# жизнью намеренно: свести их к этой функции значит тронуть `.github/workflows/**`, то есть
# сменить кнопку merge на john'а ради переноса трёх строк (названо в треде 094).
pr_body_role() { # <тело описания PR>
  printf '%s' "${1:-}" \
    | grep -oiE '^[[:space:]`*]*role`?:[[:space:]]*`?[a-z][a-z0-9-]*' | head -1 \
    | sed -E 's/^[^a-z]*role`?:[[:space:]]*`?//i'
}

# АВТОР PR — НАЗВАННЫЙ СНАРУЖИ ЛИБО ПРОЧИТАННЫЙ ИЗ ОПИСАНИЯ, и в обоих случаях сверенный с
# конфигом: `--waiting-on <роли, которой нет>` — ОТКАЗ двери, то есть письмо об отказе
# доставки потерялось бы ровно так же, как потерялся вердикт. Роль не сверилась — печатается
# пусто, и письмо всё равно едет, но БЕЗ передачи хода и сказав об этом.
# Печатает роль или ничего. Диагностика — в stderr: stdout читают подстановкой.
review_pr_author() { # <номер PR>
  local pr="${1:?review_pr_author: не назван номер PR}" role="${REVIEW_PR_AUTHOR:-}"
  if [ -z "$role" ]; then
    local body
    body="$(gh pr view "$pr" --json body -q .body 2>/dev/null)" || {
      echo "::warning::описание PR #${pr} не прочитано — автора отказу доставки назвать нечем." >&2
      return 0
    }
    role="$(pr_body_role "$body")"
  fi
  if [ -z "$role" ]; then
    echo "::warning::в описании PR #${pr} нет строки 'role: <id>' — ход по недоехавшему вердикту передать некому." >&2
    return 0
  fi
  if ! (cd .code && pnpm -F agent-protocol --silent cli role exists --repo . --ref origin/main --role "$role" >/dev/null 2>&1); then
    echo "::warning::в описании PR #${pr} названа роль '${role}', которой нет в конфиге протокола — ход по недоехавшему вердикту не передан." >&2
    return 0
  fi
  printf '%s' "$role"
}

# ТЕКСТ ОТКАЗА ДОСТАВКИ. Постановка требует НАЗВАТЬ ТРИ ВЕЩИ: какой тред не принял письмо,
# ЧЕМ он занят (чужой парк с номером) и что текст вердикта уже висит комментом в PR —
# иначе автор пойдёт искать потерянный текст, которого не терялось.
# Место вердикта берётся из ФАКТА доставки коммента (`delivery_state comment`), а не из
# предположения: коммент мог и не уехать, и тогда врать о нём нельзя (болезнь треда 082 —
# отчёт о доставках, разошедшийся с доставками).
escalation_body() { # <тред PR> <значение парка|пусто> <номер PR> <исход коммента> <url прогона|пусто> <адресат|пусто>
  local thread="${1:?}" park="${2:-}" pr="${3:?}" comment="${4:-none}" run_url="${5:-}" who="${6:-}"
  printf '⚠️ **Вердикт по PR #%s вынесен, но в тред `%s` НЕ ЛЁГ.**\n\n' "$pr" "$thread"
  if [ -n "$park" ]; then
    printf 'Тред занят: на нём стои́т парк `%s` — ЧУЖОЙ, и дверь почты права, отказывая письму рядом с ним (`run:` завершившегося круга лифт вперёд не двигает — тред `032`; `pr:` требует `--park-mover`, а имени двигателя в отказе про стоящий парк нет — тред `061`). Предел объявлен в `docs/protocol-reference.md` («Замеренный предел»), дверь по решению john 2026-09-03 не правится.\n\n' "$park"
  else
    printf 'Письмо в тред не легло, и парка, которым это объясняется, дверь не назвала — причина дословно в логе шага доставки прогона.\n\n'
  fi
  if [ "$comment" = "ok" ]; then
    printf 'ТЕКСТ ВЕРДИКТА НЕ ПОТЕРЯН: он висит комментом в самом PR #%s. Искать нечего — донести надо.\n\n' "$pr"
  else
    printf 'Коммент в PR #%s ТОЖЕ не доставлен (исход `%s`) — текст вердикта остался в логе шага доставки прогона и в артефакте транскрипта.\n\n' "$pr" "$comment"
  fi
  [ -n "$run_url" ] && printf 'Прогон: %s\n\n' "$run_url"
  if [ -n "$who" ]; then
    printf 'Ход у `%s` — автора PR (`role:` из описания). Что в его руках: перепарковать свой тред и донести вердикт письмом, либо снять и повесить метку `review` заново после смены головы, либо перенести текст руками из коммента. Приёмник — место ЗАПИСИ события, ход по вердикту здесь не его.\n' "$who"
  else
    printf '⚠️ Ход НЕ ПЕРЕДАН: автора PR назвать нечем (нет строки `role: <id>` в описании PR либо такой роли нет в конфиге) — объявите ожидание вручную.\n'
  fi
}

# ПИСЬМО ОБ ОТКАЗЕ — В ПРИЁМНИК, С ХОДОМ НА АВТОРА. Дорога та же самая (`deliver_to_thread`):
# у приёмника свой парк тоже может стоять, и читать его надо тем же сухим прогоном.
# ПИСЬМО ОДНО НА КРУГ. Шагов доставки два (вердикт и итог), и каждый зовёт `deliver_to_thread`
# по одному и тому же треду — без замка автор получил бы два письма об одном событии в
# СТОЯЧИЙ адрес. Замок ставится ДО попытки: провал самой эскалации тоже не повод писать
# второй раз, он и так громкий в прогоне (и он же обрывает рекурсию — эскалация идёт через
# ту же `deliver_to_thread`, чей отказ зовёт эскалацию).
#
# ЗАМОК — НА АДРЕСЕ, А НЕ НА КАТАЛОГЕ, и это важно ровно с той минуты, как приёмник стал
# сменяемым: закройся он между двумя шагами доставки, замок по имени каталога пропустил бы
# второе письмо — в НОВЫЙ приёмник, об одном и том же событии. Файл замка один на адрес, и
# в него же кладётся ФАКТИЧЕСКИЙ приёмник первого письма: второй шаг называет читателю лога
# тред, в котором письмо лежит, а не слаг (слаг читателю лога не адрес). Пусто в замке —
# первое письмо не легло, и об этом так и говорится, а не выдумывается номер.
escalate_undelivered() { # <тред, не принявший письмо> <значение парка|пусто> <номер PR>
  local thread="${1:?}" park="${2:-}" pr="${3:?}"
  local lock="${REVIEW_DELIVERY_DIR}/escalated"
  mkdir -p "$REVIEW_DELIVERY_DIR"
  if [ -f "$lock" ]; then
    local landed
    landed="$(tr -d '\r\n' < "$lock")"
    echo "Отказ доставки по треду ${thread} уже адресован (адрес '${REVIEW_ESCALATION_ADDRESS}', приёмник ${landed:-НЕ НАЗВАН: первое письмо не легло}) — второго письма в стоячий адрес не шлём."
    return 0
  fi
  : > "$lock"
  local who wait_args="" body
  who="$(review_pr_author "$pr")"
  [ -n "$who" ] && wait_args="--waiting-on ${who}"
  body="$(mktemp)"
  escalation_body "$thread" "$park" "$pr" "$(delivery_state comment)" "${RUN_URL:-}" "$who" > "$body"
  # shellcheck disable=SC2086 # wait_args — набор аргументов, не строка
  if deliver_to_thread "address:${REVIEW_ESCALATION_ADDRESS}" reviewer-pr "$body" \
      "chore(comms): вердикт по PR #${pr} не лёг в тред ${thread}" "$pr" ${wait_args}; then
    printf '%s\n' "$REVIEW_LANDED_THREAD" > "$lock"
    echo "Отказ доставки адресован: тред ${REVIEW_LANDED_THREAD} (адрес '${REVIEW_ESCALATION_ADDRESS}'), ход у '${who:-никого}'."
    return 0
  fi
  echo "::error::отказ доставки НЕ адресован — письмо не легло и в приёмник адреса '${REVIEW_ESCALATION_ADDRESS}'."
  return 1
}

# URL ПОЧТЫ С ТОКЕНОМ ДЖОБЫ. Токен идёт АРГУМЕНТОМ каждой команды git и в конфиг
# чекаута не садится: осевший креденшл (его вписало и отозвало действие) и был исходной
# болезнью, а Actions маскирует секрет в логе.
mail_remote_url() { # <токен> <server url> <owner/repo>
  local token="${1:?mail_remote_url: не назван токен}" server="${2:?mail_remote_url: не назван server url}" repo="${3:?mail_remote_url: не назван репозиторий}"
  printf 'https://x-access-token:%s@%s/%s' "$token" "${server#https://}" "$repo"
}

# ЧЕКАУТ ПОЧТЫ У ЭТИХ ШАГОВ — СВОЙ, и креденшл ему передаётся ЯВНО. Прежде шаг
# переиспользовал `.comms-mail`, а создаёт его САМ АГЕНТ изнутри действия: чей он
# worktree и какой конфиг делит — решает чужой прогон, а не мы (`could not read
# Username`, exit 128, прогон 30500443878, тред 023). Отсюда свой `.comms-fallback` и
# сеть по URL с `GITHUB_TOKEN`, переданным АРГУМЕНТОМ, — в конфиг он не садится:
# осевший креденшл (его вписало и отозвало действие) и был исходной болезнью.
#
# URL СОБИРАЕТСЯ ЗДЕСЬ, А НЕ В YAML, И ЭТО ПОЧИНКА ПЕРЕЕЗДА (сплошное сличение базы со
# шляпой, тред 088, по просьбе curator). Базовый шаг «Отсутствие вердикта» присваивал
# `MAIL_REMOTE=` своей строкой; переезд забрал в функцию сам чекаут, а присваивание не
# забрал — и `MAIL_REMOTE` не задавался НИГДЕ. Цена: `${MAIL_REMOTE:?}` в
# неинтерактивном bash убивает шаг НЕМЕДЛЕННО (это делает и без `set -e`), то есть
# письмо в тред не уходило бы ни на одной из двух ветвей — ровно болезнь 088,
# восстановленная её же починкой. Интеграционный прогон этого не поймал: он гоняет
# дверь напрямую, минуя `deliver_to_thread`. Отсюда — самодостаточная функция: шагу
# незачем помнить о переменной, о которой он и забыл.
review_mail_checkout() { # берёт MAIL_REMOTE, а нет его — собирает из GH_TOKEN
  MAIL_REMOTE="${MAIL_REMOTE:-$(mail_remote_url \
    "${GH_TOKEN:?review_mail_checkout: нет ни MAIL_REMOTE, ни GH_TOKEN}" \
    "${GITHUB_SERVER_URL:-https://github.com}" \
    "${GITHUB_REPOSITORY:?review_mail_checkout: не назван GITHUB_REPOSITORY}")}"
  [ -d .comms-fallback ] && return 0
  # Канонический url — ДО первой сетевой команды git (тред 016, п.1): действие вписало
  # в `remote.origin.url` свой app-токен и отозвало его перед нашими шагами, и без
  # этого падал уже fetch почты.
  git remote set-url origin "${GITHUB_SERVER_URL}/${GITHUB_REPOSITORY}"
  git fetch --no-tags "$MAIL_REMOTE" comms
  git worktree add .comms-fallback FETCH_HEAD
  git config user.name "github-actions[bot]"
  git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
}

# СЕНТИНЕЛ СУХОЙ ПРОБЫ — заведомо невозможное значение парка. Роли с таким именем нет и не
# будет (`probe:` — не `pr:` и не `run:`, а двоеточие делает имя роли нечитаемым), поэтому
# совпасть со СТОЯЩИМ парком оно не может: совпадение означало бы «лифт назван верно», дверь
# пропустила бы пробу молча и проба прочла бы «парка нет» там, где он стои́т.
PARK_PROBE_SENTINEL="${PARK_PROBE_SENTINEL:-probe:no-such-park}"

# СТОЯЩИЙ ПАРК ЧИТАЕТСЯ, А НЕ УГАДЫВАЕТСЯ — сухим прогоном той же самой команды, и
# ВОПРОС ЕЙ ЗАДАЁТСЯ ЯВНО (`--park-lifted <сентинел>`, тред 127).
#
# ПОЧЕМУ НЕ «ПРОСТО СУХОЙ ПРОГОН, КАК БЫЛО». Прежняя проба спрашивала «что скажет дверь
# ЭТОМУ письму» и брала значение парка из ОТКАЗА про молчание. Отказ этот адресован
# ПОДНЯТОЙ СЕССИИ, а #265 (тред 072) расширил исключение машинного писателя до
# `wake.mode === 'event'` целиком — то есть до `reviewer-pr`, которым и подписан весь этот
# путь. Отказ перестал приходить, `park_value_of` стала возвращать пусто НА ЛЮБОМ ПАРКЕ, и
# `park_flags` перестала строить флаг: письмо вердикта пошло в чужой парк БЕЗ `--parked-on`,
# а парк снимается лентой у первого же письма, которое его не повторило. Замер (тред 127,
# чистый `main` 80908d3e): парк `john` на треде фикстуры ПРОПАДАЕТ после письма
# `reviewer-pr`, хотя нота двери в том же выводе говорит «the park is NOT lifted and NOT
# touched by it» — она про СЕБЯ, не про ленту. Восемь красных состояний интеграционного
# прогона — все восемь — этот один дефект и есть.
#
# ПОЧЕМУ СЕНТИНЕЛ. Сверка `--park-lifted` со стоящим парком стои́т ПЕРВОЙ из парковых
# развилок двери (`park-seen.ts:156`) — раньше исключения машинного писателя, раньше
# `--parked-on`, раньше `--verdict/--pr`. Значит вопрос «какой парк стои́т» она отвечает
# ОДИНАКОВО всем писателям, и ответ приходит МАШИННОЙ формой в кавычках, а не прозой
# (`describePark` — «a decision of john's» — прозой и остаётся, и разбирать её мы не будем).
# Парка нет — дверь отвечает нотой «nothing is parked … any more» и выходит НУЛЁМ.
#
# ЧТО ЭТИМ ПОТЕРЯНО, И ЭТО СКАЗАНО ВСЛУХ. Проба больше НЕ предпросмотр записи: с сентинелом
# она отказывает там, где настоящая запись пройдёт. Предпросмотром она и не была нужна —
# `deliver_to_thread` следом зовёт настоящую запись и её отказ печатает, — но правило «сухой
# прогон есть превью записи» (cli.ts) здесь больше не работает, и ветвь «отказал НЕ по парку»
# ловит теперь не всякий будущий отказ записи, а только тот, что дверь выносит ДО парка.
# Прогон идёт ПЕРЕД КАЖДОЙ попыткой записи, поверх только что подтянутой головы почты: в тред
# пишут двое, и парк может уехать между чтением и записью.
park_probe() { # <корень почты> <адрес> <от кого> <файл тела> [прочие аргументы new-message...]
  local root="${1:?}" address="${2:?}" from="${3:?}" body="${4:?}"
  shift 4
  # Адресация у сухого прогона ТА ЖЕ, что у записи (иначе он был бы предпросмотром другого
  # письма): у стоячего адреса приёмник выбирается на том же дереве, а значит и тот же.
  local flags
  flags="$(address_flags "$address")" || return 0
  local -a addr_args
  mapfile -t addr_args <<<"$flags"
  local out
  if out=$( (cd .code && pnpm -F agent-protocol --silent cli new-message \
        --root "$root" --repo . --ref origin/main \
        "${addr_args[@]}" --from "$from" --expects answer "$@" \
        --park-lifted "$PARK_PROBE_SENTINEL" \
        --worker gh-action --body-file "$body" --no-push) 2>&1 ); then
    return 0
  fi
  local value
  value="$(park_value_of "$out")"
  if [ -z "$value" ]; then
    # Сухой прогон отказал НЕ ПО ПАРКУ — печатаем дословно: настоящая запись сейчас
    # отвалится тем же отказом, и он должен быть в логе один раз до, а не только
    # после.
    #
    # `>&2` ЗДЕСЬ — НЕ ОФОРМЛЕНИЕ, А ОТВЕТ (замер curator, тред 088, чтение ветки):
    # stdout этой функции читают подстановкой (`park="$(park_probe …)"`), поэтому
    # напечатанное сюда предупреждение НЕ попадает в лог прогона, а садится в
    # значение парка — и `park_flags` выдаёт `--parked-on <текст предупреждения>`.
    # Дверь такое письмо отказывает, круг снова теряет вердикт, а причина, которую
    # предупреждение объясняло, в логе не появляется вовсе. Правило общее: всё, что
    # печатается ВНУТРИ функции, чей stdout читают подстановкой, идёт в stderr.
    echo "::warning::сухой прогон new-message отказал не по парку — запись, скорее всего, отвалится тем же: ${out}" >&2
    return 0
  fi
  printf '%s' "$value"
}

# ПИСЬМО В ТРЕД — одна дверь на обе ветви (вердикт есть / вердикта нет). Возвращает 0,
# если письмо ЛЕГЛО и уехало; 1 — если нет, и причина напечатана.
deliver_to_thread() { # <адрес: <NNN-слаг> либо address:<слаг>> <от кого> <файл тела> <сообщение коммита> <номер PR> [прочие аргументы new-message...]
  local address="${1:?}" from="${2:?}" body="${3:?}" commit_msg="${4:?}" pr="${5:?}"
  shift 5
  local root="${GITHUB_WORKSPACE}/.comms-fallback/agent-comms"
  local flags
  flags="$(address_flags "$address")" || return 1
  local -a addr_args
  mapfile -t addr_args <<<"$flags"
  # ТРЕД, НЕ ПРИНЯВШИЙ ПИСЬМО, называется эскалации по АДРЕСУ — до записи фактического
  # приёмника у стоячего адреса нет, и подставлять туда слаг нельзя: слаг не тред.
  local thread="${address#address:}"
  REVIEW_LANDED_THREAD=""
  review_mail_checkout
  # Каталог спрашивается только у ИМЕНОВАННОГО треда. У стоячего адреса его отсутствие —
  # законный случай, а не отказ: приёмника этого слага может не быть вовсе, и письмо его
  # ОТКРОЕТ. Отказ здесь похоронил бы звонок ровно в тот день, ради которого адрес стоячий.
  if [ "$thread" = "$address" ] && [ ! -d "${root}/${thread}/messages" ]; then
    echo "::warning::Каталога .comms-fallback/agent-comms/${thread}/messages нет — в тред не сообщено."
    escalate_undelivered "$thread" "" "$pr"
    return 1
  fi
  COMMS_PUSH_DIR=.comms-fallback
  COMMS_PUSH_REMOTE="$MAIL_REMOTE"
  local attempt park park_args landed letter=""
  for attempt in $(seq 1 "$COMMS_PUSH_ATTEMPTS"); do
    git -C .comms-fallback fetch --no-tags "$MAIL_REMOTE" comms
    git -C .comms-fallback reset --hard FETCH_HEAD
    # ПРИЁМНИК РЕШАЕТСЯ ВНУТРИ ПОПЫТКИ, а не до цикла: у стоячего адреса он выбирается по
    # той ленте, на которую мы сейчас пишем, — потому и сухой прогон, и запись стоят ПОСЛЕ
    # `reset --hard`.
    park="$(park_probe "$root" "$address" "$from" "$body" "$@")"
    # shellcheck disable=SC2046 # аргументы флага парка разделяются по словам намеренно
    park_args=$(park_flags "$park" "$pr")
    [ -n "$park" ] && echo "На адресате '${address}' стои́т парк '${park}' — письмо идёт с '${park_args}'."
    # shellcheck disable=SC2086 # $park_args и $@ — набор аргументов, не строка
    if ! (cd .code && pnpm -F agent-protocol --silent cli new-message \
          --root "$root" --repo . --ref origin/main \
          "${addr_args[@]}" --from "$from" --expects answer "$@" ${park_args} \
          --worker gh-action --body-file "$body" --write --no-push); then
      echo "::error::new-message отказал — по адресу '${address}' НЕ сообщено."
      escalate_undelivered "$thread" "$park" "$pr"
      return 1
    fi
    landed="$(landed_thread "$(git -C .comms-fallback -c core.quotePath=false status \
      --porcelain --untracked-files=all -- agent-comms)")"
    if [ -z "$landed" ]; then
      # Успех команды без записи в дерево — не «доставлено», а расхождение отчёта с
      # фактом, то есть болезнь треда 082 с другой стороны. Коммитить нечего, повторять
      # попытку нечем: следующая попытка сделала бы ровно то же самое.
      echo "::error::new-message отчитался об успехе, но под agent-comms/ ничего не появилось — по адресу '${address}' НЕ сообщено."
      escalate_undelivered "$thread" "$park" "$pr"
      return 1
    fi
    REVIEW_LANDED_THREAD="$landed"
    git -C .comms-fallback add -A
    # --no-verify НЕ послабление стиля: worktree'ы делят `.git`, а с ним и хуки,
    # установленные `pnpm install` в главном чекауте; коммит почты звал бы pre-commit
    # главного репозитория (`Command "turbo" not found`, прогон 30521214435).
    git -C .comms-fallback commit --no-verify -m "$commit_msg"
    # ПУТЬ СВОЕГО ПИСЬМА — из своего же коммита, ДО следующей попытки: она начинается с
    # `reset --hard`, и после неё спрашивать «что я написал» уже не у кого. Он и есть
    # опознание письма для пробы ниже.
    #
    # КАТАЛОГ БЕРЁТСЯ ИЗ `landed`, А НЕ ИЗ `thread` (стык с тредом 125): у СТОЯЧЕГО адреса
    # `thread` — это слаг, а не имя каталога, и грепом по слагу свой файл не нашёлся бы
    # никогда. Фактический приёмник знает только дерево, и его уже спросил `landed_thread`.
    letter="$(git -C .comms-fallback show --pretty=format: --name-only --diff-filter=A HEAD \
      | grep -m1 "^agent-comms/${landed}/messages/" || true)"
    if comms_push "$attempt"; then
      echo "Доставлено в тред ${landed}."
      return 0
    fi
  done
  # ПОТЕРЯННАЯ КВИТАНЦИЯ И ЗДЕСЬ (тред 122): push мог лечь на сервер, а ответ — потеряться
  # в сети. Перечитываем удалённую ленту и ищем СВОЙ файл, прежде чем объявить письмо
  # непришедшим; не нашли — всё как сегодня, включая адресацию отказа автору PR.
  #
  # ДОСТАВКА НАЗЫВАЕТСЯ ФАКТИЧЕСКИМ ПРИЁМНИКОМ (`landed`), а не адресом: у стоячего адреса
  # читателю лога нужен тред, в котором письмо лежит, — слаг ему не адрес (тред 125).
  # `REVIEW_LANDED_THREAD` на этой ветви НЕ обнуляется: письмо легло, и эскалации, которая
  # его читает, здесь всё равно нет.
  if delivery_confirmed "письмо в тред ${landed:-${thread}}" 1 delivery_probe_thread_file "$letter"; then
    return 0
  fi
  REVIEW_LANDED_THREAD=""
  echo "::error::Не удалось сообщить по адресу '${address}' за ${COMMS_PUSH_ATTEMPTS} попыток."
  escalate_undelivered "$thread" "$park" "$pr"
  return 1
}
